SELECT i.careunit, CASE WHEN i.careunit IN (SELECT careunit FROM icustays) THEN admissions_1_3.num_studies ELSE admissions_4_7.num_studies END AS num_studies FROM icustays i JOIN (SELECT careunit, COUNT(DISTINCT hadm_id) AS num_studies FROM admissions WHERE EXTRACT(YEAR FROM age(CURRENT_DATE, MIN(dischtime))) BETWEEN 1 AND 3 GROUP BY careunit) AS admissions_1_3 ON i.careunit = admissions_1_3.careunit JOIN (SELECT careunit, COUNT(DISTINCT hadm_id) AS num_studies FROM admissions WHERE EXTRACT(YEAR FROM age(CURRENT_DATE, MIN(dischtime))) BETWEEN 4 AND 7 GROUP BY careunit) AS admissions_4_7 ON i.careunit = admissions_4_7.careunit ORDER BY i.careunit NULLS LAST;